/*
 * @lc app=leetcode id=3013 lang=kotlin
 *
 * [3013] Divide an Array Into Subarrays With Minimum Cost II
 */

class Solution { fun minimumCost(nums: IntArray, k: Int, dist: Int): Long = java.util.TreeMap<Int, Int>().let { low -> java.util.TreeMap<Int, Int>().let { high -> longArrayOf(0, 0, 0L, (k - 1).toLong()).let { st -> { mp: java.util.TreeMap<Int, Int>, x: Int -> mp.put(x, mp.getOrDefault(x, 0) + 1) }.let { addMap -> { mp: java.util.TreeMap<Int, Int>, x: Int -> mp.get(x)!!.let { if (it == 1) mp.remove(x) else mp.put(x, it - 1) } }.let { remMap -> { generateSequence { }.takeWhile { st[0] > minOf(st[3], st[0] + st[1]) }.forEach { low.lastKey().let { lx -> remMap(low, lx).also { st[0]-- }.also { st[2] -= lx }.also { addMap(high, lx) }.also { st[1]++ } } }.run { generateSequence { }.takeWhile { st[0] < minOf(st[3], st[0] + st[1]) && st[1] > 0 }.forEach { high.firstKey().let { hx -> remMap(high, hx).also { st[1]-- }.also { addMap(low, hx) }.also { st[0]++ }.also { st[2] += hx } } } } }.let { balance -> { x: Int -> (if (st[0] == 0L || x <= low.lastKey()) addMap(low, x).also { st[0]++ }.also { st[2] += x } else addMap(high, x).also { st[1]++ }).run { balance() } }.let { addVal -> { x: Int -> (if (low.containsKey(x)) remMap(low, x).also { st[0]-- }.also { st[2] -= x } else remMap(high, x).also { st[1]-- }).run { balance() } }.let { remVal -> (1..minOf(dist, nums.size - 1)).forEach { addVal(nums[it]) }.run { (2..nums.size - dist - 1).fold(st[2]) { minSum, i -> remVal(nums[i - 1]).run { addVal(nums[i + dist]) }.run { minOf(minSum, st[2]) } } + nums[0] } } } } } } } } }